-- Hostel complaints, canteen and day-scholar menu; visitors, gate passes, incidents; student health, medical visits, first aid.
CREATE SEQUENCE public.hostel_complaint_seq START 148;
CREATE TABLE public.hostel_complaints (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(10) NOT NULL DEFAULT ('HC-' || lpad(nextval('public.hostel_complaint_seq')::text, 4, '0')), student_id UUID REFERENCES public.students(id) ON DELETE SET NULL, room_code VARCHAR(12) NOT NULL DEFAULT '', issue VARCHAR(160) NOT NULL, assigned_to VARCHAR(80) NOT NULL DEFAULT '', status VARCHAR(12) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Assigned', 'In progress', 'Resolved')), raised_on DATE NOT NULL DEFAULT CURRENT_DATE, resolved_on DATE);
CREATE TABLE public.canteen_items (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(60) NOT NULL, price INTEGER NOT NULL CHECK (price >= 0), peanuts BOOLEAN NOT NULL DEFAULT false, active BOOLEAN NOT NULL DEFAULT true, UNIQUE (institution_id, name));
CREATE TABLE public.canteen_wallets (student_id UUID PRIMARY KEY REFERENCES public.students(id) ON DELETE CASCADE, institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, balance INTEGER NOT NULL DEFAULT 0 CHECK (balance >= 0), daily_limit INTEGER NOT NULL DEFAULT 150 CHECK (daily_limit >= 0));
CREATE TABLE public.canteen_sales (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, items VARCHAR(300) NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), sold_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.day_menu_items (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, menu_date DATE NOT NULL, slot VARCHAR(8) NOT NULL CHECK (slot IN ('morning', 'lunch', 'evening')), name VARCHAR(80) NOT NULL, peanuts BOOLEAN NOT NULL DEFAULT false, pos INTEGER NOT NULL DEFAULT 0);
CREATE TABLE public.day_menu_published (institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, week_start DATE NOT NULL, published_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (institution_id, week_start));
CREATE SEQUENCE public.mess_req_seq START 412;
ALTER TABLE public.mess_requests ADD COLUMN code VARCHAR(10) NOT NULL DEFAULT ('MR-' || lpad(nextval('public.mess_req_seq')::text, 4, '0')), ADD COLUMN parent_name VARCHAR(80) NOT NULL DEFAULT '', ADD COLUMN start_on DATE;

CREATE TABLE public.visitors (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, visit_date DATE NOT NULL DEFAULT CURRENT_DATE, name VARCHAR(80) NOT NULL, purpose VARCHAR(30) NOT NULL, details VARCHAR(200) NOT NULL DEFAULT '', meeting VARCHAR(80) NOT NULL DEFAULT '', id_type VARCHAR(20) NOT NULL DEFAULT '', id_last4 VARCHAR(4) NOT NULL DEFAULT '', in_time VARCHAR(5), out_time VARCHAR(5), status VARCHAR(18) NOT NULL DEFAULT 'Awaiting approval' CHECK (status IN ('Awaiting approval', 'Approved', 'Checked in', 'Checked out', 'Rejected', 'Cancelled')));
CREATE SEQUENCE public.gate_pass_seq START 234;
CREATE TABLE public.gate_passes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL, for_kind VARCHAR(8) NOT NULL CHECK (for_kind IN ('Student', 'Staff')), person_ref UUID, name VARCHAR(80) NOT NULL, class_dept VARCHAR(40) NOT NULL DEFAULT '', reason VARCHAR(160) NOT NULL, out_at VARCHAR(5), picked_up_by VARCHAR(80) NOT NULL DEFAULT '', pass_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(18) NOT NULL DEFAULT 'Pending approval' CHECK (status IN ('Pending approval', 'Expected', 'Left', 'Returned', 'Rejected')), UNIQUE (institution_id, code));
CREATE SEQUENCE public.incident_seq START 35;
CREATE TABLE public.campus_incidents (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(10) NOT NULL DEFAULT ('INC-' || lpad(nextval('public.incident_seq')::text, 4, '0')), what VARCHAR(200) NOT NULL, location VARCHAR(60) NOT NULL, reported_by VARCHAR(80) NOT NULL, incident_date DATE NOT NULL DEFAULT CURRENT_DATE, severity VARCHAR(8) NOT NULL CHECK (severity IN ('Low', 'Medium', 'High')), status VARCHAR(14) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Investigating', 'Closed')));
CREATE TABLE public.emergency_contacts (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, service VARCHAR(80) NOT NULL, number VARCHAR(60) NOT NULL, distance VARCHAR(20) NOT NULL DEFAULT '', status VARCHAR(12) NOT NULL DEFAULT 'Not verified' CHECK (status IN ('Not verified', 'Verified')), UNIQUE (institution_id, service));

CREATE TABLE public.student_health (student_id UUID PRIMARY KEY REFERENCES public.students(id) ON DELETE CASCADE, institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, blood_group VARCHAR(4) NOT NULL DEFAULT '', allergies VARCHAR(160) NOT NULL DEFAULT '', conditions VARCHAR(160) NOT NULL DEFAULT '', contact1_name VARCHAR(80) NOT NULL DEFAULT '', contact1_mobile VARCHAR(20) NOT NULL DEFAULT '', contact2_name VARCHAR(80) NOT NULL DEFAULT '', contact2_mobile VARCHAR(20) NOT NULL DEFAULT '');
CREATE TABLE public.student_vaccines (student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, vaccine VARCHAR(20) NOT NULL, status VARCHAR(8) NOT NULL CHECK (status IN ('Given', 'Due', 'Not due')), PRIMARY KEY (student_id, vaccine));
CREATE SEQUENCE public.health_update_seq START 2042;
CREATE TABLE public.parent_health_updates (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(10) NOT NULL DEFAULT ('HU-' || nextval('public.health_update_seq')::text), student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, parent_name VARCHAR(80) NOT NULL DEFAULT '', kind VARCHAR(16) NOT NULL CHECK (kind IN ('Vaccination card', 'Medical note')), details VARCHAR(300) NOT NULL, attachment VARCHAR(120) NOT NULL DEFAULT '', sent_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(10) NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'Accepted', 'Returned')));
CREATE TABLE public.medical_visits (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, visit_date DATE NOT NULL DEFAULT CURRENT_DATE, student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, complaint VARCHAR(60) NOT NULL, treatment VARCHAR(120) NOT NULL, seen_by VARCHAR(80) NOT NULL, in_time VARCHAR(5), status VARCHAR(14) NOT NULL DEFAULT 'In clinic' CHECK (status IN ('In clinic', 'Back to class', 'Sent home', 'Hospital')));
CREATE SEQUENCE public.first_aid_seq START 68;
CREATE TABLE public.first_aid (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(10) NOT NULL DEFAULT ('IR-' || lpad(nextval('public.first_aid_seq')::text, 4, '0')), student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, what VARCHAR(160) NOT NULL, place VARCHAR(60) NOT NULL DEFAULT '', severity VARCHAR(8) NOT NULL CHECK (severity IN ('Minor', 'Moderate', 'Serious')), parent_told VARCHAR(60) NOT NULL DEFAULT '', incident_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(10) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Follow-up', 'Closed')));
ALTER TABLE public.hostel_complaints ENABLE ROW LEVEL SECURITY; ALTER TABLE public.canteen_items ENABLE ROW LEVEL SECURITY; ALTER TABLE public.canteen_wallets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.canteen_sales ENABLE ROW LEVEL SECURITY; ALTER TABLE public.day_menu_items ENABLE ROW LEVEL SECURITY; ALTER TABLE public.day_menu_published ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.visitors ENABLE ROW LEVEL SECURITY; ALTER TABLE public.gate_passes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.campus_incidents ENABLE ROW LEVEL SECURITY; ALTER TABLE public.emergency_contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.student_health ENABLE ROW LEVEL SECURITY; ALTER TABLE public.student_vaccines ENABLE ROW LEVEL SECURITY; ALTER TABLE public.parent_health_updates ENABLE ROW LEVEL SECURITY; ALTER TABLE public.medical_visits ENABLE ROW LEVEL SECURITY; ALTER TABLE public.first_aid ENABLE ROW LEVEL SECURITY;
